/**
 * PROTOTYPE DATA — THROWAWAY.
 *
 * Real loading filmstrips captured from the site below with a CDP screencast (the mechanism
 * Lighthouse uses), under Lighthouse-like throttling: mobile = 4x CPU slowdown + 1.6 Mbps /
 * 150 ms RTT, desktop = 10 Mbps / 40 ms RTT.
 *
 * 'before' was captured with every Boost module off; 'after' with Critical CSS, Defer JS,
 * Image CDN and Minify on. Both sides were captured warm (caches and the image CDN primed)
 * and each is the MEDIAN of three runs by load time, so neither side is cherry-picked.
 *
 * Frames and timings are genuine; they are baked in only so the UI can be judged without
 * building the capture pipeline. Nothing in the product produces this data today.
 */

export type FilmstripFrame = {
	offsetMs: number;
	src: string;
};

export type FilmstripMetrics = {
	fcp: number;
	lcp: number;
	domContentLoaded: number;
	load: number;
};

export type VariantCapture = {
	metrics: FilmstripMetrics;
	frames: FilmstripFrame[];
};

export type FilmstripVariant = 'before' | 'after';
export type FilmstripDevice = 'mobile' | 'desktop';

export type FilmstripProfile = {
	label: string;
	viewport: { width: number; height: number };
	before: VariantCapture;
	after: VariantCapture;
};

export const CAPTURED_URL = 'https://supposed-crawdad-starlight.jurassic.ninja/';
export const CAPTURED_AT = '2026-08-19';
export const BOOST_MODULES = 'Critical CSS, Defer JS, Image CDN, Minify';

